test("captures UART Dock CH342F pad shorts after Pipeline 9 completes", async (): Promise<void> => {
  const solver = new AutoroutingPipelineSolver9_PreloadedTraceGraph(
    structuredClone(input),
    { cacheProvider: null },
  )
  solver.solve()
  expect(solver.solved).toBe(true)
  expect(solver.failed).toBe(false)
  const routedTraces = solver.getOutputSimplifiedPcbTraces()
  const snapshotInput = {
    inputSrj: input,
    srjWithPointPairs: solver.srjWithPointPairs!,
    routedTraces,
  }
  const { errors } = evaluateRelaxedDrc(snapshotInput)
  // Capture the actual CTS1-to-RTS1 pad contact, not just a clearance warning.
  expect(errors.some((error) =>
    error.type === "pcb_trace_error" &&
    error.pcb_trace_error_id === "overlap_source_net_21_0_pcb_smtpad_54",
  )).toBe(true)

  const graphics = convertSrjToGraphicsObject({ ...input, traces: routedTraces })
  graphics.points = []
  // Match graphics-debug's projection; only the snapshot camera is cropped.
  // See tests/fixtures/getA13ViaCleanupSnapshotSvg.ts for the same pattern.
  const transform = computeTransformFromViewbox(getBounds(graphics), 640, 640, {
    padding: 40,
    yFlip: true,
  })
  const topLeft = applyToPoint(transform, { x: -4.7, y: 14.3 })
  const bottomRight = applyToPoint(transform, { x: 0.5, y: 9.6 })
  const labelHeight = Math.abs(
    applyToPoint(transform, { x: 0, y: 0.16 }).y -
    applyToPoint(transform, { x: 0, y: 0 }).y,
  )
  const labels = [
    { x: -1.898269, y: 12.249936, text: "9" },
    { x: -1.898269, y: 11.750064, text: "10" },
    { x: -1.898269, y: 11.249938, text: "11" },
    { x: -0.4, y: 12.000762, text: "25 / GND" },
  ].map(({ x, y, text }) => {
    const p = applyToPoint(transform, { x, y })
    return `<text x="${p.x}" y="${p.y}" font-size="${labelHeight}" font-family="sans-serif" text-anchor="middle" dominant-baseline="middle" fill="#111827">${text}</text>`
  }).join("")
  const contents = getBugReportSnapshotSvg(snapshotInput)
    .replace(/^<svg[^>]*>/, "")
    .replace(/<\/svg>$/, "")
  const svg = `<svg width="900" height="900" viewBox="0 0 900 900" xmlns="http://www.w3.org/2000/svg">
    <rect width="900" height="900" fill="white"/>
    <text x="24" y="34" font-family="sans-serif" font-size="24" fill="#111827">UART Dock — CH342F pad shorts</text>
    <text x="24" y="64" font-family="sans-serif" font-size="18" fill="#b91c1c">Pipeline 9 completed; relaxed DRC errors across the input: ${errors.length}</text>
    <svg x="0" y="85" width="900" height="760" viewBox="${topLeft.x} ${topLeft.y} ${bottomRight.x - topLeft.x} ${bottomRight.y - topLeft.y}">${contents}${labels}</svg>
    <text x="24" y="870" font-family="sans-serif" font-size="18" fill="#111827">9: RST · 10: CTS1 · 11: RTS1 · 25: GND | Red: top copper; blue: bottom</text>
  </svg>`
  await expect(svg).toMatchSvgSnapshot(import.meta.path)
})
